.cfc-sw-review-item {
  display: flex !important;
  flex-direction: row !important; /* This absolutely forces side-by-side layout */
  flex-wrap: nowrap !important; /* Stops the text from wrapping under the avatar */
  align-items: flex-start !important;
  gap: 16px !important;
  width: 100%;
}

#div-catkpy {
  animation: cfc-slide-1 15s infinite;
}

@keyframes cfc-slide-1 {
  0%, 28% { opacity: 1; pointer-events: auto; }
  33%, 95% { opacity: 0; pointer-events: none; }
  100% { opacity: 1; pointer-events: auto; }
}

/* Base Avatar (LOCKED DOWN TO A CIRCLE) */
.cfc-sw-avatar {
  width: 44px;
  height: 44px;
  min-width: 44px; /* Prevents squishing */
  flex-shrink: 0; /* Tells flexbox it is not allowed to shrink this item */
  border-radius: 50% !important; /* Enforces the perfect circle */
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  font-weight: 700;
}

